<?php get_header();while(have_posts()):the_post();$cat=franklem_first_category();$slug=$cat?$cat->slug:'politica';$data=franklem_section_data();$color=isset($data[$slug])?$data[$slug][1]:'#e84b38';$byline=get_post_meta(get_the_ID(),'franklem_byline',true)?:get_the_author(); ?><main class="article-shell" style="--section:<?php echo esc_attr($color); ?>"><article><a class="category-tag" href="<?php echo $cat?esc_url(get_category_link($cat)):esc_url(home_url('/')); ?>"><?php echo $cat?esc_html($cat->name):'Notícias'; ?></a><h1 class="entry-title"><?php the_title(); ?></h1><?php if($sub=franklem_subtitle()): ?><p class="entry-subtitle"><?php echo esc_html($sub); ?></p><?php endif; ?><div class="entry-meta"><span>Por <?php echo esc_html($byline); ?></span><time datetime="<?php echo esc_attr(get_the_date(DATE_W3C)); ?>"><?php echo esc_html(get_the_date('d/m/Y \à\s H:i')); ?></time><span>Atualizado <?php echo esc_html(get_the_modified_date('d/m/Y \à\s H:i')); ?></span></div><?php if(has_post_thumbnail())the_post_thumbnail('full',['class'=>'featured-image']); ?><div class="entry-content"><?php the_content(); ?></div><div class="ad-slot">ESPAÇO RESERVADO PARA PUBLICIDADE</div></article></main><?php endwhile;get_footer(); ?>
